    return []

def _data_adjust(obj):
    """
    event data adjust:
    """
    id = obj.id
    data = obj.model_dump(exclude={"id"})
    data.update({"id": id})
    if hasattr(obj, "tools"):
        data["tools"] = _data_adjust_tools(data["tools"])

